// [AI-GENERATED DISCLAIMER START: Autonomously generated by an AI agent]
/**
 * Novation Launchpad X MIDI script for Mixxx Groove Station
 *
 * Layout matches Mixxx Groove Station 1:1 top-to-bottom:
 * - Row 8 (top grid row, Notes 81-88): Track 1 KICK
 * - Row 7 (Notes 71-78): Track 2 SNARE
 * - Row 6 (Notes 61-68): Track 3 CLAP
 * - Row 5 (Notes 51-58): Track 4 CLOSED HAT
 * - Row 4 (Notes 41-48): Track 5 OPEN HAT
 * - Row 3 (Notes 31-38): Track 6 LOW TOM
 * - Row 2 (Notes 21-28): Track 7 HIGH TOM
 * - Row 1 (bottom grid row, Notes 11-18): Track 8 CRASH
 *
 * Right Column Scene Buttons (89..19 top to bottom):
 * - Scene 89: Instant Kick trigger with velocity
 * - Scene 79: Instant Snare trigger with velocity
 * - Scene 69: Instant Clap trigger with velocity
 * - Scene 59: Instant Closed Hat trigger with velocity
 * - Scene 49: Instant Open Hat trigger with velocity
 * - Scene 39: Instant Low Tom trigger with velocity
 * - Scene 29: Instant High Tom trigger with velocity
 * - Scene 19: Instant Crash trigger with velocity
 * - Shift (Custom CC 97) + Scene button: Mute toggle
 *
 * Top Buttons (CC 91..98):
 * - CC 91 (▲ Up): Siguiente Patrón (1-8)
 * - CC 92 (▼ Down): Siguiente Kit de Sonidos (1-4)
 * - CC 93 (◄ Left): Página 1 (Pasos 1-8)
 * - CC 94 (► Right): Página 2 (Pasos 9-16)
 * - CC 95 (Session): PLAY / PAUSA
 * - CC 96 (Note): Conmutar Modo Secuenciador <-> Modo 8 Pads Grandes
 * - CC 97 (Custom): Shift / Mute / Borrar
 * - CC 98 (Record): Grabar (Shift + Record = Borrar Patrón)
 */

var LaunchpadX = {};

// Paleta de colores Novation Launchpad X (0..127) según la guía oficial y GrooveStation.qml
LaunchpadX.Colors = {
    OFF: 0,
    DIM_WHITE: 1,
    MED_WHITE: 2,
    BRIGHT_WHITE: 3,

    // Colores exactos 1:1 con la interfaz de Groove Station:
    // 1. KICK:     #ff5252 (Rojo vivo)        -> Paleta 5 (dim: 7)
    // 2. SNARE:    #ffab40 (Naranja)          -> Paleta 9 (dim: 11)
    // 3. CLAP:     #ffd740 (Ámbar / Amarillo) -> Paleta 13 (dim: 15)
    // 4. HAT:      #69f0ae (Verde menta)      -> Paleta 29 (dim: 31)
    // 5. OPEN HAT: #64ffda (Cian / Aqua)      -> Paleta 37 (dim: 39)
    // 6. LOW TOM:  #40c4ff (Azul cielo)       -> Paleta 41 (dim: 43)
    // 7. HIGH TOM: #b388ff (Violeta / Púrpura)-> Paleta 53 (dim: 55)
    // 8. CRASH:    #ff4081 (Rosa / Magenta)   -> Paleta 57 (dim: 59)
    KICK: 5,
    SNARE: 9,
    CLAP: 13,
    CLOSED_HAT: 29,
    OPEN_HAT: 37,
    LOW_TOM: 41,
    HIGH_TOM: 53,
    CRASH: 57,

    // Colores atenuados (para pistas silenciadas / mute)
    KICK_DIM: 7,
    SNARE_DIM: 11,
    CLAP_DIM: 15,
    CLOSED_HAT_DIM: 31,
    OPEN_HAT_DIM: 39,
    LOW_TOM_DIM: 43,
    HIGH_TOM_DIM: 55,
    CRASH_DIM: 59,

    // Botones de función y estados
    PLAY_GREEN: 21,
    PLAY_DIM: 23,
    REC_RED: 5,
    REC_DIM: 7,
    PAGE_ACTIVE: 3,
    PAGE_INACTIVE: 1,
    MUTED_RED: 5,
    SOLO_YELLOW: 13,
    PATTERN_ACTIVE: 13,
    PATTERN_INACTIVE: 15,
    KIT_ACTIVE: 41,
    KIT_INACTIVE: 43,
    DRUM_MODE_COLOR: 57
};

// Pistas en orden de arriba a abajo (Track 1 = Kick, ..., Track 8 = Crash)
LaunchpadX.TrackColors = [
    LaunchpadX.Colors.KICK,
    LaunchpadX.Colors.SNARE,
    LaunchpadX.Colors.CLAP,
    LaunchpadX.Colors.CLOSED_HAT,
    LaunchpadX.Colors.OPEN_HAT,
    LaunchpadX.Colors.LOW_TOM,
    LaunchpadX.Colors.HIGH_TOM,
    LaunchpadX.Colors.CRASH
];

LaunchpadX.TrackColorsDim = [
    LaunchpadX.Colors.KICK_DIM,
    LaunchpadX.Colors.SNARE_DIM,
    LaunchpadX.Colors.CLAP_DIM,
    LaunchpadX.Colors.CLOSED_HAT_DIM,
    LaunchpadX.Colors.OPEN_HAT_DIM,
    LaunchpadX.Colors.LOW_TOM_DIM,
    LaunchpadX.Colors.HIGH_TOM_DIM,
    LaunchpadX.Colors.CRASH_DIM
];

LaunchpadX.page = 0;              // 0: Pasos 1-8, 1: Pasos 9-16
LaunchpadX.autoFollow = true;     // Seguir automáticamente el cursor entre páginas
LaunchpadX.drumMode = false;      // false = Secuenciador, true = Modo 8 Pads Finger Drumming
LaunchpadX.shiftActive = false;   // CC 97 pulsado
LaunchpadX.currentStep = -1;      // Paso actual del cursor (-1 cuando está parado)
LaunchpadX.connections = [];

// Conversión física:
// Track 1 (Kick, fila superior de la pantalla) -> Fila física 8 (notas 81..88)
// Track 8 (Crash, fila inferior de la pantalla) -> Fila física 1 (notas 11..18)
LaunchpadX.trackToGridRow = function(track) {
    return 9 - track; // 1->8, 2->7, ..., 8->1
};

LaunchpadX.gridRowToTrack = function(gridRow) {
    return 9 - gridRow; // 8->1, 7->2, ..., 1->8
};

// Enviar SysEx para modo DAW y Session Layout en el puerto LPX DAW (Port 0):
// https://userguides.novationmusic.com/hc/en-gb/articles/24001475492498-Controlling-the-Launchpad-X-surface
LaunchpadX.enterDAWMode = function() {
    console.log("LaunchpadX: Configurando modo DAW y Session Layout en puerto DAW (Port 0)...");

    // 1. Activar alimentación de LEDs / Despertar suspensión (Comando 0x09, valor 0x01 = WAKE)
    midi.sendSysexMsg([0xF0, 0x00, 0x20, 0x29, 0x02, 0x0C, 0x09, 0x01, 0xF7], 9);

    // 2. Ajustar brillo de LEDs al máximo (Comando 0x08, nivel 0x7F = 127)
    midi.sendSysexMsg([0xF0, 0x00, 0x20, 0x29, 0x02, 0x0C, 0x08, 0x7F, 0xF7], 9);

    // 3. Salir de modo Programmer y volver a Live Mode (Comando 0x0E, valor 0x00 = Live Mode)
    midi.sendSysexMsg([0xF0, 0x00, 0x20, 0x29, 0x02, 0x0C, 0x0E, 0x00, 0xF7], 9);

    // 4. Activar MODO DAW (Comando 0x10, valor 0x01 = DAW Mode ON)
    midi.sendSysexMsg([0xF0, 0x00, 0x20, 0x29, 0x02, 0x0C, 0x10, 0x01, 0xF7], 9);

    // 5. Seleccionar diseño SESSION (Comando 0x00, layout 0x00 = Session layout)
    midi.sendSysexMsg([0xF0, 0x00, 0x20, 0x29, 0x02, 0x0C, 0x00, 0x00, 0xF7], 9);
};

LaunchpadX.exitDAWMode = function() {
    console.log("LaunchpadX: Desactivando Modo DAW (Standalone)...");
    // 1. Desactivar MODO DAW (Comando 0x10, valor 0x00 = Standalone)
    midi.sendSysexMsg([0xF0, 0x00, 0x20, 0x29, 0x02, 0x0C, 0x10, 0x00, 0xF7], 9);
    // 2. Volver a Live Mode (Comando 0x0E, valor 0x00)
    midi.sendSysexMsg([0xF0, 0x00, 0x20, 0x29, 0x02, 0x0C, 0x0E, 0x00, 0xF7], 9);
};

// Helpers LED
LaunchpadX.setLED = function(status, midino, color) {
    midi.sendShortMsg(status, midino, color);
    if (midino >= 19 && midino <= 89 && (midino % 10 === 9)) {
        midi.sendShortMsg(status === 0xB0 ? 0x90 : 0xB0, midino, color);
    }
};

LaunchpadX.setFlashLED = function(isCC, midino, color) {
    midi.sendShortMsg(isCC ? 0xB1 : 0x91, midino, color);
};

LaunchpadX.setPulseLED = function(isCC, midino, color) {
    midi.sendShortMsg(isCC ? 0xB2 : 0x92, midino, color);
};

LaunchpadX.init = function(id, debugging) {
    LaunchpadX.id = id;
    console.log("LaunchpadX: inicializando mapeo Groove Station...");

    // Entrar en modo DAW y Session Layout
    LaunchpadX.enterDAWMode();

    // Conectar eventos del motor de Mixxx
    LaunchpadX.connectControls();

    // Dibujar estado inicial tras breve retardo para asegurar que el firmware procesó el SysEx
    engine.beginTimer(100, function() {
        LaunchpadX.enterDAWMode();
        LaunchpadX.refreshAll();
    }, true);

    // Segundo refresco de sincronización a los 300ms
    engine.beginTimer(300, function() {
        LaunchpadX.refreshAll();
        console.log("LaunchpadX: iluminacion lista y sincronizada.");
    }, true);
};

LaunchpadX.shutdown = function() {
    for (var i = 0; i < LaunchpadX.connections.length; ++i) {
        if (LaunchpadX.connections[i]) {
            LaunchpadX.connections[i].disconnect();
        }
    }
    LaunchpadX.connections = [];
    LaunchpadX.clearAllLEDs();
    LaunchpadX.exitDAWMode();
    console.log("LaunchpadX: apagado completado.");
};

LaunchpadX.clearAllLEDs = function() {
    for (var r = 1; r <= 8; ++r) {
        for (var c = 1; c <= 8; ++c) {
            midi.sendShortMsg(0x90, r * 10 + c, 0);
        }
        midi.sendShortMsg(0xB0, r * 10 + 9, 0);
        midi.sendShortMsg(0x90, r * 10 + 9, 0);
    }
    for (var cc = 91; cc <= 98; ++cc) {
        midi.sendShortMsg(0xB0, cc, 0);
    }
};

LaunchpadX.connectControls = function() {
    LaunchpadX.connections.push(
        engine.makeConnection("[GrooveStation]", "step", LaunchpadX.onStepChanged)
    );
    LaunchpadX.connections.push(
        engine.makeConnection("[GrooveStation]", "play", LaunchpadX.onPlayChanged)
    );
    LaunchpadX.connections.push(
        engine.makeConnection("[GrooveStation]", "record", LaunchpadX.onRecordChanged)
    );
    LaunchpadX.connections.push(
        engine.makeConnection("[GrooveStation]", "pattern", LaunchpadX.onPatternChanged)
    );
    LaunchpadX.connections.push(
        engine.makeConnection("[GrooveStation]", "kit", LaunchpadX.onKitChanged)
    );

    for (var t = 1; t <= 8; ++t) {
        LaunchpadX.connections.push(
            engine.makeConnection("[GrooveStation]", "mute_" + t, LaunchpadX.onMuteChanged)
        );
        LaunchpadX.connections.push(
            engine.makeConnection("[GrooveStation]", "solo_" + t, LaunchpadX.onSoloChanged)
        );
    }

    for (var trk = 1; trk <= 8; ++trk) {
        for (var stp = 1; stp <= 16; ++stp) {
            LaunchpadX.connections.push(
                engine.makeConnection("[GrooveStation]", "cell_" + trk + "_" + stp, LaunchpadX.onCellChanged)
            );
        }
    }
};

// Playhead step: cursor en tiempo real
LaunchpadX.onStepChanged = function(value) {
    var step = Math.round(value);

    // Si está parado (-1)
    if (step < 0) {
        if (LaunchpadX.currentStep >= 0 && !LaunchpadX.drumMode) {
            var prevStep = LaunchpadX.currentStep;
            var prevPage = Math.floor(prevStep / 8);
            if (prevPage === LaunchpadX.page) {
                LaunchpadX.refreshColumn(prevStep % 8);
            }
        }
        LaunchpadX.currentStep = -1;
        LaunchpadX.updatePlayButton();
        return;
    }

    // Auto-follow: cambiar de página automáticamente con el compás
    if (LaunchpadX.autoFollow && !LaunchpadX.drumMode) {
        var neededPage = (step >= 8) ? 1 : 0;
        if (neededPage !== LaunchpadX.page) {
            LaunchpadX.page = neededPage;
            LaunchpadX.refreshGrid();
            LaunchpadX.updatePageButtons();
        }
    }

    if (!LaunchpadX.drumMode) {
        // Restaurar columna anterior
        if (LaunchpadX.currentStep >= 0 && LaunchpadX.currentStep !== step) {
            var oldStep = LaunchpadX.currentStep;
            var oldPage = Math.floor(oldStep / 8);
            if (oldPage === LaunchpadX.page) {
                LaunchpadX.refreshColumn(oldStep % 8);
            }
        }

        // Iluminar columna actual del cursor
        var currPage = Math.floor(step / 8);
        if (currPage === LaunchpadX.page) {
            var col = step % 8;
            for (var trk = 1; trk <= 8; ++trk) {
                var gridRow = LaunchpadX.trackToGridRow(trk);
                var note = gridRow * 10 + (col + 1);
                var stepNum = LaunchpadX.page * 8 + col + 1;
                var cellVal = engine.getValue("[GrooveStation]", "cell_" + trk + "_" + stepNum);

                if (cellVal > 0) {
                    // Si hay golpe activo: ¡destello blanco radiante!
                    LaunchpadX.setLED(0x90, note, LaunchpadX.Colors.BRIGHT_WHITE);
                } else {
                    // Paso inactivo: línea suave blanca del cursor
                    LaunchpadX.setLED(0x90, note, LaunchpadX.Colors.DIM_WHITE);
                }
            }
        }
    }

    LaunchpadX.currentStep = step;
    LaunchpadX.updatePlayButton();
};

LaunchpadX.onPlayChanged = function(value) {
    LaunchpadX.updatePlayButton();
};

LaunchpadX.onRecordChanged = function(value) {
    LaunchpadX.updateRecordButton();
};

LaunchpadX.onPatternChanged = function(value) {
    LaunchpadX.flashTrackRow(1, LaunchpadX.Colors.BRIGHT_WHITE);
};

LaunchpadX.onKitChanged = function(value) {
    LaunchpadX.flashAll(LaunchpadX.Colors.KIT_ACTIVE);
};

LaunchpadX.onMuteChanged = function(value, group, key) {
    var track = parseInt(key.replace("mute_", ""), 10);
    LaunchpadX.updateSceneButton(track);
    if (!LaunchpadX.drumMode) {
        LaunchpadX.refreshTrackRow(track);
    }
};

LaunchpadX.onSoloChanged = function(value, group, key) {
    var track = parseInt(key.replace("solo_", ""), 10);
    LaunchpadX.updateSceneButton(track);
};

LaunchpadX.onCellChanged = function(value, group, key) {
    if (LaunchpadX.drumMode) {
        return;
    }
    var parts = key.split("_");
    if (parts.length < 3) return;
    var track = parseInt(parts[1], 10);
    var step = parseInt(parts[2], 10);
    var col = (step - 1) % 8;
    var page = Math.floor((step - 1) / 8);

    if (page === LaunchpadX.page) {
        if (step - 1 === LaunchpadX.currentStep) {
            var gridRow = LaunchpadX.trackToGridRow(track);
            var note = gridRow * 10 + (col + 1);
            LaunchpadX.setLED(0x90, note, value > 0 ? LaunchpadX.Colors.BRIGHT_WHITE : LaunchpadX.Colors.DIM_WHITE);
        } else {
            LaunchpadX.drawCell(track, col);
        }
    }
};

// Dibujado de celdas
LaunchpadX.drawCell = function(track, col) {
    var gridRow = LaunchpadX.trackToGridRow(track);
    var note = gridRow * 10 + (col + 1);
    var stepNum = LaunchpadX.page * 8 + col + 1;
    var cellVal = engine.getValue("[GrooveStation]", "cell_" + track + "_" + stepNum);
    var muteVal = engine.getValue("[GrooveStation]", "mute_" + track);

    var color = LaunchpadX.Colors.OFF;
    if (cellVal > 0) {
        color = (muteVal > 0) ? LaunchpadX.TrackColorsDim[track - 1] : LaunchpadX.TrackColors[track - 1];
    } else {
        // Marcador visible de tiempo en los pulsos 1 y 5 (blanco suave)
        if (col === 0 || col === 4) {
            color = LaunchpadX.Colors.MED_WHITE;
        } else {
            color = LaunchpadX.Colors.OFF;
        }
    }
    LaunchpadX.setLED(0x90, note, color);
};

LaunchpadX.refreshColumn = function(col) {
    for (var trk = 1; trk <= 8; ++trk) {
        LaunchpadX.drawCell(trk, col);
    }
};

LaunchpadX.refreshTrackRow = function(track) {
    for (var c = 0; c < 8; ++c) {
        LaunchpadX.drawCell(track, c);
    }
};

LaunchpadX.refreshGrid = function() {
    if (LaunchpadX.drumMode) {
        // 8 Pads gigantes de 4x2 pads estilo MPC
        // Bloque superior (Filas 8-7): Track 1 Kick (izq) y Track 2 Snare (der)
        // Filas 6-5: Track 3 Clap (izq) y Track 4 Closed Hat (der)
        // Filas 4-3: Track 5 Open Hat (izq) y Track 6 Low Tom (der)
        // Filas 2-1: Track 7 High Tom (izq) y Track 8 Crash (der)
        for (var r = 1; r <= 8; ++r) {
            for (var c = 1; c <= 8; ++c) {
                var blockRow = Math.floor((8 - r) / 2); // 0..3
                var blockCol = (c > 4) ? 1 : 0;
                var trackIdx = blockRow * 2 + blockCol; // 0..7
                var note = r * 10 + c;
                LaunchpadX.setLED(0x90, note, LaunchpadX.TrackColors[trackIdx]);
            }
        }
        return;
    }

    for (var c = 0; c < 8; ++c) {
        LaunchpadX.refreshColumn(c);
    }
};

LaunchpadX.updatePlayButton = function() {
    var isPlaying = engine.getValue("[GrooveStation]", "play") > 0;
    if (isPlaying) {
        LaunchpadX.setLED(0xB0, 95, LaunchpadX.Colors.PLAY_GREEN);
    } else {
        LaunchpadX.setPulseLED(true, 95, LaunchpadX.Colors.PLAY_DIM);
    }
};

LaunchpadX.updateRecordButton = function() {
    var isRec = engine.getValue("[GrooveStation]", "record") > 0;
    if (isRec) {
        LaunchpadX.setFlashLED(true, 98, LaunchpadX.Colors.REC_RED);
    } else {
        LaunchpadX.setLED(0xB0, 98, LaunchpadX.Colors.REC_DIM);
    }
};

LaunchpadX.updatePageButtons = function() {
    LaunchpadX.setLED(0xB0, 93, LaunchpadX.page === 0 ? LaunchpadX.Colors.PAGE_ACTIVE : LaunchpadX.Colors.PAGE_INACTIVE);
    LaunchpadX.setLED(0xB0, 94, LaunchpadX.page === 1 ? LaunchpadX.Colors.PAGE_ACTIVE : LaunchpadX.Colors.PAGE_INACTIVE);
};

LaunchpadX.updateModeButton = function() {
    LaunchpadX.setLED(0xB0, 96, LaunchpadX.drumMode ? LaunchpadX.Colors.DRUM_MODE_COLOR : LaunchpadX.Colors.CLOSED_HAT);
};

LaunchpadX.updateSceneButton = function(track) {
    var gridRow = LaunchpadX.trackToGridRow(track);
    var midino = gridRow * 10 + 9;
    var isMuted = engine.getValue("[GrooveStation]", "mute_" + track) > 0;
    var isSolo = engine.getValue("[GrooveStation]", "solo_" + track) > 0;

    if (isMuted) {
        LaunchpadX.setLED(0xB0, midino, LaunchpadX.Colors.MUTED_RED);
        LaunchpadX.setLED(0x90, midino, LaunchpadX.Colors.MUTED_RED);
    } else if (isSolo) {
        LaunchpadX.setPulseLED(true, midino, LaunchpadX.Colors.SOLO_YELLOW);
        LaunchpadX.setPulseLED(false, midino, LaunchpadX.Colors.SOLO_YELLOW);
    } else {
        LaunchpadX.setLED(0xB0, midino, LaunchpadX.TrackColors[track - 1]);
        LaunchpadX.setLED(0x90, midino, LaunchpadX.TrackColors[track - 1]);
    }
};

LaunchpadX.updateAllSceneButtons = function() {
    for (var trk = 1; trk <= 8; ++trk) {
        LaunchpadX.updateSceneButton(trk);
    }
};

LaunchpadX.sendFullSysExState = function() {
    var specs = [];

    // 64 Grid Pads
    for (var r = 1; r <= 8; ++r) {
        var trk = LaunchpadX.gridRowToTrack(r);
        var muteVal = engine.getValue("[GrooveStation]", "mute_" + trk);
        for (var c = 0; c < 8; ++c) {
            var note = r * 10 + (c + 1);
            var color = LaunchpadX.Colors.OFF;
            if (LaunchpadX.drumMode) {
                var blockRow = Math.floor((8 - r) / 2);
                var blockCol = (c >= 4) ? 1 : 0;
                var trackIdx = blockRow * 2 + blockCol;
                color = LaunchpadX.TrackColors[trackIdx];
            } else {
                var stepNum = LaunchpadX.page * 8 + c + 1;
                var cellVal = engine.getValue("[GrooveStation]", "cell_" + trk + "_" + stepNum);
                if (LaunchpadX.currentStep >= 0 && stepNum - 1 === LaunchpadX.currentStep) {
                    color = cellVal > 0 ? LaunchpadX.Colors.BRIGHT_WHITE : LaunchpadX.Colors.DIM_WHITE;
                } else if (cellVal > 0) {
                    color = (muteVal > 0) ? LaunchpadX.TrackColorsDim[trk - 1] : LaunchpadX.TrackColors[trk - 1];
                } else if (c === 0 || c === 4) {
                    color = LaunchpadX.Colors.MED_WHITE;
                } else {
                    color = LaunchpadX.Colors.OFF;
                }
            }
            specs.push([0, note, color]);
        }
    }

    // 8 Scene buttons (columna derecha: 19..89)
    for (var t = 1; t <= 8; ++t) {
        var gr = LaunchpadX.trackToGridRow(t);
        var sNote = gr * 10 + 9;
        var isM = engine.getValue("[GrooveStation]", "mute_" + t) > 0;
        var isS = engine.getValue("[GrooveStation]", "solo_" + t) > 0;
        var scColor = isM ? LaunchpadX.Colors.MUTED_RED : (isS ? LaunchpadX.Colors.SOLO_YELLOW : LaunchpadX.TrackColors[t - 1]);
        specs.push([0, sNote, scColor]);
    }

    // 9 Botones superiores (91..99)
    var isPl = engine.getValue("[GrooveStation]", "play") > 0;
    var isRc = engine.getValue("[GrooveStation]", "record") > 0;
    specs.push([0, 91, LaunchpadX.Colors.PATTERN_ACTIVE]);
    specs.push([0, 92, LaunchpadX.Colors.KIT_ACTIVE]);
    specs.push([0, 93, LaunchpadX.page === 0 ? LaunchpadX.Colors.PAGE_ACTIVE : LaunchpadX.Colors.PAGE_INACTIVE]);
    specs.push([0, 94, LaunchpadX.page === 1 ? LaunchpadX.Colors.PAGE_ACTIVE : LaunchpadX.Colors.PAGE_INACTIVE]);
    specs.push([0, 95, isPl ? LaunchpadX.Colors.PLAY_GREEN : LaunchpadX.Colors.PLAY_DIM]);
    specs.push([0, 96, LaunchpadX.drumMode ? LaunchpadX.Colors.DRUM_MODE_COLOR : LaunchpadX.Colors.CLOSED_HAT]);
    specs.push([0, 97, LaunchpadX.shiftActive ? LaunchpadX.Colors.BRIGHT_WHITE : 0]);
    specs.push([0, 98, isRc ? LaunchpadX.Colors.REC_RED : LaunchpadX.Colors.REC_DIM]);
    specs.push([0, 99, LaunchpadX.Colors.CLOSED_HAT]);

    // Enviar SysEx en bloques de hasta 30 LEDs por paquete para máxima seguridad
    var batchSize = 30;
    for (var b = 0; b < specs.length; b += batchSize) {
        var chunk = specs.slice(b, b + batchSize);
        var sysex = [0xF0, 0x00, 0x20, 0x29, 0x02, 0x0C, 0x03];
        for (var j = 0; j < chunk.length; ++j) {
            sysex.push(chunk[j][0]); // type (0 = static palette)
            sysex.push(chunk[j][1]); // led index
            sysex.push(chunk[j][2]); // color
        }
        sysex.push(0xF7);
        midi.sendSysexMsg(sysex, sysex.length);
    }
};

LaunchpadX.refreshAll = function() {
    LaunchpadX.refreshGrid();
    LaunchpadX.updateAllSceneButtons();
    LaunchpadX.updatePlayButton();
    LaunchpadX.updateRecordButton();
    LaunchpadX.updatePageButtons();
    LaunchpadX.updateModeButton();
    LaunchpadX.setLED(0xB0, 91, LaunchpadX.Colors.PATTERN_ACTIVE);
    LaunchpadX.setLED(0xB0, 92, LaunchpadX.Colors.KIT_ACTIVE);
    LaunchpadX.setLED(0xB0, 97, LaunchpadX.shiftActive ? LaunchpadX.Colors.BRIGHT_WHITE : 0);
    LaunchpadX.setLED(0xB0, 99, LaunchpadX.Colors.CLOSED_HAT);
    LaunchpadX.sendFullSysExState();
};

LaunchpadX.flashAll = function(color) {
    for (var r = 1; r <= 8; ++r) {
        for (var c = 1; c <= 8; ++c) {
            LaunchpadX.setLED(0x90, r * 10 + c, color);
        }
    }
    engine.beginTimer(120, function() {
        LaunchpadX.refreshGrid();
    }, true);
};

LaunchpadX.flashTrackRow = function(track, color) {
    var gridRow = LaunchpadX.trackToGridRow(track);
    for (var c = 1; c <= 8; ++c) {
        LaunchpadX.setLED(0x90, gridRow * 10 + c, color);
    }
    engine.beginTimer(100, function() {
        LaunchpadX.refreshTrackRow(track);
    }, true);
};

// Handlers MIDI de Entrada
LaunchpadX.gridPad = function(channel, control, value, status, group) {
    var isPressed = (status !== 0x80 && value > 0);
    var gridRow = Math.floor(control / 10);
    var col = (control % 10) - 1;

    if (gridRow < 1 || gridRow > 8 || col < 0 || col > 7) {
        return;
    }

    // Modo 8 Pads Finger Drumming
    if (LaunchpadX.drumMode) {
        var blockRow = Math.floor((8 - gridRow) / 2); // 0..3
        var blockCol = (col >= 4) ? 1 : 0;
        var trackIdx = blockRow * 2 + blockCol;
        var trackNum = trackIdx + 1;

        if (isPressed) {
            var velocity = Math.max(0.3, value / 127.0);
            engine.setValue("[GrooveStation]", "pad_" + trackNum, velocity);
            // Destello en el bloque tocado
            var rStart = (3 - blockRow) * 2 + 1;
            var cStart = (blockCol === 1) ? 5 : 1;
            for (var dr = 0; dr < 2; ++dr) {
                for (var dc = 0; dc < 4; ++dc) {
                    LaunchpadX.setLED(0x90, (rStart + dr) * 10 + (cStart + dc), LaunchpadX.Colors.BRIGHT_WHITE);
                }
            }
        } else {
            engine.setValue("[GrooveStation]", "pad_" + trackNum, 0.0);
            var rStart = (3 - blockRow) * 2 + 1;
            var cStart = (blockCol === 1) ? 5 : 1;
            for (var dr = 0; dr < 2; ++dr) {
                for (var dc = 0; dc < 4; ++dc) {
                    LaunchpadX.setLED(0x90, (rStart + dr) * 10 + (cStart + dc), LaunchpadX.TrackColors[trackIdx]);
                }
            }
        }
        return;
    }

    // Modo Secuenciador por pasos (1:1 con la pantalla)
    var track = LaunchpadX.gridRowToTrack(gridRow);
    var stepNum = LaunchpadX.page * 8 + col + 1;

    if (isPressed) {
        var currentVal = engine.getValue("[GrooveStation]", "cell_" + track + "_" + stepNum);
        if (currentVal > 0) {
            engine.setValue("[GrooveStation]", "cell_" + track + "_" + stepNum, 0.0);
            console.log("LaunchpadX: Track " + track + ", Paso " + stepNum + " -> OFF");
        } else {
            var hitVel = Math.max(0.7, value / 127.0);
            engine.setValue("[GrooveStation]", "cell_" + track + "_" + stepNum, hitVel);
            // Vista previa de sonido inmediata:
            engine.setValue("[GrooveStation]", "pad_" + track, hitVel);
            engine.beginTimer(90, function() {
                engine.setValue("[GrooveStation]", "pad_" + track, 0.0);
            }, true);
            console.log("LaunchpadX: Track " + track + ", Paso " + stepNum + " -> ON (vel " + hitVel.toFixed(2) + ")");
        }
    }
};

LaunchpadX.sceneButton = function(channel, control, value, status, group) {
    var isPressed = (status !== 0x80 && value > 0);
    var gridRow = Math.floor(control / 10);
    if (gridRow < 1 || gridRow > 8) return;
    var track = LaunchpadX.gridRowToTrack(gridRow);

    console.log("LaunchpadX.sceneButton: Track " + track + " (ctrl " + control + ") -> " + (isPressed ? "PRESIONADO (vel " + value + ")" : "SOLTADO"));

    if (isPressed) {
        if (LaunchpadX.shiftActive) {
            // Shift + botón lateral: Conmutar Mute
            var currentMute = engine.getValue("[GrooveStation]", "mute_" + track);
            engine.setValue("[GrooveStation]", "mute_" + track, currentMute > 0 ? 0 : 1);
        } else {
            // Botón lateral: Disparar sonido del instrumento con velocidad
            var velocity = Math.max(0.4, value / 127.0);
            engine.setValue("[GrooveStation]", "pad_" + track, velocity);
            LaunchpadX.setLED(0xB0, control, LaunchpadX.Colors.BRIGHT_WHITE);
            LaunchpadX.setLED(0x90, control, LaunchpadX.Colors.BRIGHT_WHITE);
        }
    } else {
        if (!LaunchpadX.shiftActive) {
            engine.setValue("[GrooveStation]", "pad_" + track, 0.0);
            LaunchpadX.updateSceneButton(track);
        }
    }
};

LaunchpadX.topButton = function(channel, control, value, status, group) {
    var isPressed = (status !== 0x80 && value > 0);
    console.log("LaunchpadX.topButton: CC " + control + " -> " + (isPressed ? "PRESIONADO" : "SOLTADO"));

    switch (control) {
        case 91: // ▲ Up: Siguiente Patrón (1..8)
            if (isPressed) {
                var curPattern = Math.round(engine.getValue("[GrooveStation]", "pattern"));
                var nextPattern = (curPattern + 1) % 8;
                engine.setValue("[GrooveStation]", "pattern", nextPattern);
                console.log("LaunchpadX: Patrón " + (nextPattern + 1));
            }
            break;

        case 92: // ▼ Down: Siguiente Kit (1..4)
            if (isPressed) {
                var curKit = Math.round(engine.getValue("[GrooveStation]", "kit"));
                var nextKit = (curKit + 1) % 4;
                engine.setValue("[GrooveStation]", "kit", nextKit);
                console.log("LaunchpadX: Kit " + (nextKit + 1));
            }
            break;

        case 93: // ◄ Left: Página 1 (Pasos 1-8)
            if (isPressed) {
                LaunchpadX.page = 0;
                LaunchpadX.refreshGrid();
                LaunchpadX.updatePageButtons();
            }
            break;

        case 94: // ► Right: Página 2 (Pasos 9-16)
            if (isPressed) {
                LaunchpadX.page = 1;
                LaunchpadX.refreshGrid();
                LaunchpadX.updatePageButtons();
            }
            break;

        case 95: // Session: PLAY / PAUSA
            if (isPressed) {
                var playing = engine.getValue("[GrooveStation]", "play");
                engine.setValue("[GrooveStation]", "play", playing > 0 ? 0 : 1);
            }
            break;

        case 96: // Note: Alternar Secuenciador <-> Finger Drumming (8 Pads)
            if (isPressed) {
                LaunchpadX.drumMode = !LaunchpadX.drumMode;
                LaunchpadX.refreshGrid();
                LaunchpadX.updateModeButton();
            }
            break;

        case 97: // Custom: Shift (Mute / Borrar)
            LaunchpadX.shiftActive = isPressed;
            LaunchpadX.setLED(0xB0, 97, isPressed ? LaunchpadX.Colors.CLAP : 0);
            break;

        case 98: // Record: Grabar / Borrar
            if (isPressed) {
                if (LaunchpadX.shiftActive) {
                    // Shift + Record = Borrar todo el patrón
                    engine.setValue("[GrooveStation]", "clear", 1.0);
                    LaunchpadX.flashAll(LaunchpadX.Colors.KICK);
                } else {
                    var rec = engine.getValue("[GrooveStation]", "record");
                    engine.setValue("[GrooveStation]", "record", rec > 0 ? 0 : 1);
                }
            } else {
                if (LaunchpadX.shiftActive) {
                    engine.setValue("[GrooveStation]", "clear", 0.0);
                }
            }
            break;
    }
};

